macro_rules! QueryModifiers {
    () => {
        struct QueryModifiers { # [doc = " The description of the query."] desc : (Option < Ident > , Punctuated < Expr , Token ! [,] >) , # [doc = " Use this type for the in-memory cache."] arena_cache : Option < Ident > , # [doc = " Cache the query to disk if the `Block` returns true."] cache : Option < (Option < Pat > , Block) > , # [doc = " A cycle error for this query aborting the compilation with a fatal error."] fatal_cycle : Option < Ident > , # [doc = " A cycle error results in a delay_bug call"] cycle_delay_bug : Option < Ident > , # [doc = " A cycle error results in a stashed cycle error that can be unstashed and canceled later"] cycle_stash : Option < Ident > , # [doc = " Don't hash the result, instead just mark a query red if it runs"] no_hash : Option < Ident > , # [doc = " Generate a dep node based on the dependencies of the query"] anon : Option < Ident > , # [doc = " Always evaluate the query, ignoring its dependencies"] eval_always : Option < Ident > , # [doc = " Whether the query has a call depth limit"] depth_limit : Option < Ident > , # [doc = " Use a separate query provider for local and extern crates"] separate_provide_extern : Option < Ident > , # [doc = " Generate a `feed` method to set the query's value from another query."] feedable : Option < Ident > , # [doc = " When this query is called via `tcx.ensure_ok()`, it returns"] # [doc = " `Result<(), ErrorGuaranteed>` instead of `()`. If the query needs to"] # [doc = " be executed, and that execution returns an error, the error result is"] # [doc = " returned to the caller."] # [doc = ""] # [doc = " If execution is skipped, a synthetic `Ok(())` is returned, on the"] # [doc = " assumption that a query with all-green inputs must have succeeded."] # [doc = ""] # [doc = " Can only be applied to queries with a return value of"] # [doc = " `Result<_, ErrorGuaranteed>`."] return_result_from_ensure_ok : Option < Ident > , }
    };
}

QueryModifiers!();